// Validate the intake payload under the pinned webhook envelope.
// n8n 2.37.10 Webhook v2 nests the POST body under `body` and exposes the
// request headers under `headers` (verified against the pinned image).
const raw = $input.first().json;
const input = raw.body ?? raw;
const errors = [];

// Stable caller-supplied idempotency key: HTTP header first, body field as a
// convenience fallback. No key, no staging — fail closed.
const key = String(raw.headers?.['x-intake-idempotency-key'] ?? input.idempotency_key ?? '').trim();
if (!key) errors.push('Missing intake idempotency key (X-Intake-Idempotency-Key header)');

if (!input.contact?.first_name) errors.push('Missing first_name');
if (!input.contact?.last_name) errors.push('Missing last_name');
if (!input.contact?.email && !input.contact?.phone) errors.push('Missing email and phone — need at least one');
if (!input.case_info?.type) errors.push('Missing case type');
if (!input.case_info?.description) errors.push('Missing case description');

// Normalize phone to E.164 if present
let phone = input.contact?.phone || '';
if (phone && !phone.startsWith('+')) {
  phone = '+1' + phone.replace(/\D/g, '');
}

// Strip nulls/empty strings
const cleanContact = Object.fromEntries(
  Object.entries(input.contact || {}).filter(([_, v]) => v != null && v !== '')
);

const normalized = {
  contact: { ...cleanContact, ...(phone ? { phone } : {}) },
  case_info: input.case_info,
  source: input.source || 'unknown',
  referral_source: input.referral_source || 'unknown',
  timestamp: input.timestamp || null,
  firm: 'Greenfield & Associates'
};

// Inline SHA-256 (the pinned sandbox forbids require) over the canonical
// JSON of the six normalized delivery-relevant fields — the exact
// canonicalization the demo state service recomputes authoritatively, so
// the graph itself proves payload integrity before staging.
const sha256hex = (ascii) => {
  const rightRotate = (value, amount) => (value >>> amount) | (value << (32 - amount));
  const maxWord = Math.pow(2, 32);
  let result = '';
  const words = [];
  const asciiBitLength = ascii.length * 8;
  let hash = sha256hex.h = sha256hex.h || [];
  const k = sha256hex.k = sha256hex.k || [];
  let primeCounter = k.length;
  const isComposite = {};
  for (let candidate = 2; primeCounter < 64; candidate++) {
    if (!isComposite[candidate]) {
      for (let i = 0; i < 313; i += candidate) isComposite[i] = candidate;
      hash[primeCounter] = (Math.pow(candidate, 0.5) * maxWord) | 0;
      k[primeCounter++] = (Math.pow(candidate, 1 / 3) * maxWord) | 0;
    }
  }
  ascii += '\x80';
  while (ascii.length % 64 - 56) ascii += '\x00';
  for (let i = 0; i < ascii.length; i++) {
    const j = ascii.charCodeAt(i);
    if (j >> 8) return null;
    words[i >> 2] |= j << (((3 - i) % 4) * 8);
  }
  words[words.length] = (asciiBitLength / maxWord) | 0;
  words[words.length] = asciiBitLength;
  for (let j = 0; j < words.length;) {
    const w = words.slice(j, j += 16);
    const oldHash = hash;
    hash = hash.slice(0, 8);
    for (let i = 0; i < 64; i++) {
      const w15 = w[i - 15];
      const w2 = w[i - 2];
      const a = hash[0];
      const e = hash[4];
      const temp1 = hash[7]
        + (rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25))
        + ((e & hash[5]) ^ (~e & hash[6]))
        + k[i]
        + (w[i] = i < 16 ? w[i] : (
          w[i - 16]
          + (rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3))
          + w[i - 7]
          + (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10))
        ) | 0);
      const temp2 = (rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22))
        + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));
      hash = [(temp1 + temp2) | 0].concat(hash);
      hash[4] = (hash[4] + temp1) | 0;
    }
    for (let i = 0; i < 8; i++) hash[i] = (hash[i] + oldHash[i]) | 0;
  }
  for (let i = 0; i < 8; i++) {
    for (let j = 3; j + 1; j--) {
      const b = (hash[i] >> (j * 8)) & 255;
      result += (b < 16 ? '0' : '') + b.toString(16);
    }
  }
  return result;
};
const canonical = (v) => Array.isArray(v)
  ? '[' + v.map(canonical).join(',') + ']'
  : (v !== null && typeof v === 'object')
    ? '{' + Object.keys(v).sort().map((key) => JSON.stringify(key) + ':' + canonical(v[key])).join(',') + '}'
    : JSON.stringify(v ?? null);

const canonicalString = canonical({
  contact: normalized.contact,
  case_info: normalized.case_info,
  source: normalized.source,
  referral_source: normalized.referral_source,
  firm: normalized.firm,
  timestamp: normalized.timestamp,
});
const payloadHash = sha256hex(unescape(encodeURIComponent(canonicalString)));

return [{
  json: {
    valid: errors.length === 0,
    errors,
    idempotency_key: key,
    payload_hash: payloadHash,
    contact: normalized.contact,
    case_info: normalized.case_info,
    source: normalized.source,
    referral_source: normalized.referral_source,
    timestamp: normalized.timestamp,
    firm: normalized.firm
  }
}];

// Interpret the demo state service's staged-intake response. Fail closed:
// ONLY an explicit status=staged (201) or status=replay (200) body maps to a
// truthful staged/replay outcome; the mock's 409 conflict body maps to an
// explicit conflict; every other shape (non-fictional rejection, malformed,
// unexpected) is a refusal whose own status code is surfaced — never a
// pending-review claim.
const body = $input.first().json;
const isObject = body !== null && typeof body === 'object' && !Array.isArray(body);
if (isObject && body.status === 'staged' && typeof body.review_id === 'string') {
  return [{ json: { outcome: 'staged', review_id: body.review_id, review_state: body.review_state ?? 'pending' } }];
}
if (isObject && body.status === 'replay' && typeof body.review_id === 'string') {
  return [{ json: { outcome: 'replay', review_id: body.review_id, review_state: body.review_state ?? 'unknown' } }];
}
if (isObject && body.code === 409) {
  return [{ json: { outcome: 'conflict', refused_code: 409, refusal: typeof body.error === 'string' ? body.error : 'idempotency key conflict — a duplicate request is never approval' } }];
}
const refusal = isObject && typeof body.error === 'string'
  ? body.error
  : 'the demo state service refused the staging — nothing was queued';
const refusedCode = isObject && typeof body.code === 'number' ? body.code : 400;
return [{ json: { outcome: 'refused', refused_code: refusedCode, refusal } }];
